#!/usr/bin/env bash
# kbd-phase-status.sh — KBD phase lifecycle hook: begin/end status banner + log + user hooks
#
# Usage: kbd-phase-status.sh <step> <begin|end>
#   step:  assess | plan | execute | reflect
#   event: begin | end
#
# Outputs:
#   - Banner to stdout (visible in agent terminal)
#   - Appended row to .kbd-orchestrator/phase-log.md
#   - Dispatches matching entries from .kbd-orchestrator/hooks-config.json
#
# Environment variables exported for user hook commands:
#   KBD_PROJECT_ROOT, KBD_PROJECT_NAME, PHASE, STEP, EVENT,
#   CHANGES_TOTAL, CHANGES_COMPLETED, LAST_UPDATED_BY, TIMESTAMP

set -euo pipefail

STEP="${1:-unknown}"
EVENT="${2:-begin}"

# ── Locate project root (walk up until .kbd-orchestrator/ found) ───────────
find_project_root() {
  local dir="${PWD}"
  while [[ "$dir" != "/" ]]; do
    [[ -d "${dir}/.kbd-orchestrator" ]] && { echo "$dir"; return; }
    dir="$(dirname "$dir")"
  done
  echo "${PWD}"  # fallback: current dir
}

PROJECT_ROOT="$(find_project_root)"
KBD_DIR="${PROJECT_ROOT}/.kbd-orchestrator"
WAYPOINT="${KBD_DIR}/current-waypoint.json"
HOOKS_CONFIG="${KBD_DIR}/hooks-config.json"
PHASE_LOG="${KBD_DIR}/phase-log.md"
TIMESTAMP="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"

# ── Read waypoint ──────────────────────────────────────────────────────────
PHASE="unknown"
LAST_UPDATED_BY="unknown"
CHANGES_TOTAL=0
CHANGES_COMPLETED=0

if [[ -f "$WAYPOINT" ]]; then
  PHASE="$(python3 -c "import json; d=json.load(open('$WAYPOINT')); print(d.get('phase','unknown'))" 2>/dev/null || echo "unknown")"
fi

# ── Read progress.json if available ───────────────────────────────────────
PROGRESS_FILE="${KBD_DIR}/phases/${PHASE}/progress.json"
GOALS_STATUS=""
if [[ -f "$PROGRESS_FILE" ]]; then
  CHANGES_TOTAL="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print(d.get('changes_total',0))" 2>/dev/null || echo 0)"
  CHANGES_COMPLETED="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print(d.get('changes_completed',0))" 2>/dev/null || echo 0)"
  LAST_UPDATED_BY="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print(d.get('last_updated_by','unknown'))" 2>/dev/null || echo "unknown")"
  ASSESS="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print('v' if d.get('assessment_complete') else '_')" 2>/dev/null || echo "_")"
  PLAN="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print('v' if d.get('plan_complete') else '_')" 2>/dev/null || echo "_")"
  EXEC="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print('v' if d.get('execution_dispatched') else '_')" 2>/dev/null || echo "_")"
  REFL="$(python3 -c "import json; d=json.load(open('$PROGRESS_FILE')); print('v' if d.get('reflection_complete') else '_')" 2>/dev/null || echo "_")"
  GOALS_STATUS="[${ASSESS}] assess  [${PLAN}] plan  [${EXEC}] execute  [${REFL}] reflect"
fi

# ── Read project name ──────────────────────────────────────────────────────
PROJECT_JSON="${KBD_DIR}/project.json"
KBD_PROJECT_NAME="unknown"
if [[ -f "$PROJECT_JSON" ]]; then
  KBD_PROJECT_NAME="$(python3 -c "import json; d=json.load(open('$PROJECT_JSON')); print(d.get('name','unknown'))" 2>/dev/null || echo "unknown")"
fi

export KBD_PROJECT_ROOT="$PROJECT_ROOT"
export KBD_PROJECT_NAME
export PHASE STEP EVENT CHANGES_TOTAL CHANGES_COMPLETED LAST_UPDATED_BY TIMESTAMP

# ── Step ordinal and next step ────────────────────────────────────────────
case "$STEP" in
  assess)  ORDINAL=1; NEXT_STEP="/kbd-plan" ;;
  plan)    ORDINAL=2; NEXT_STEP="/kbd-execute" ;;
  execute) ORDINAL=3; NEXT_STEP="/kbd-reflect" ;;
  reflect) ORDINAL=4; NEXT_STEP="/kbd-next-phase" ;;
  *)       ORDINAL="?"; NEXT_STEP="(unknown)" ;;
esac

EVENT_LABEL="BEGINNING"
[[ "$EVENT" == "end" ]] && EVENT_LABEL="COMPLETED"

# ── Banner ────────────────────────────────────────────────────────────────
echo ""
echo "=================================================================="
printf "KBD  %-36s [%s kbd-%s]\n" "$KBD_PROJECT_NAME" "$EVENT_LABEL" "$STEP"
echo "Phase:   ${PHASE}"
echo "Step:    ${ORDINAL} of 4 -- ${STEP}"
if [[ -n "$GOALS_STATUS" ]]; then
  echo "Steps:   ${GOALS_STATUS}"
fi
if [[ "$CHANGES_TOTAL" -gt 0 ]]; then
  REMAINING=$(( CHANGES_TOTAL - CHANGES_COMPLETED ))
  echo "Changes: ${CHANGES_TOTAL} total / ${CHANGES_COMPLETED} done / ${REMAINING} remaining"
fi
if [[ "$EVENT" == "end" ]]; then
  echo "Next:    ${NEXT_STEP}"
fi
echo "Updated: ${LAST_UPDATED_BY} @ ${TIMESTAMP}"
echo "=================================================================="
echo ""

# ── Append to phase-log.md ────────────────────────────────────────────────
if [[ ! -f "$PHASE_LOG" ]]; then
  {
    echo "# KBD Phase Activity Log"
    echo ""
    echo "Auto-generated by \`kbd-phase-status.sh\`. Do not edit manually."
    echo ""
    echo "| Timestamp | Phase | Step | Event | Changes | Tool |"
    echo "|-----------|-------|------|-------|---------|------|"
  } > "$PHASE_LOG"
fi

echo "| ${TIMESTAMP} | ${PHASE} | ${STEP} | ${EVENT} | ${CHANGES_COMPLETED}/${CHANGES_TOTAL} | ${LAST_UPDATED_BY} |" >> "$PHASE_LOG"

# ── Dispatch user-configured hooks ────────────────────────────────────────
if [[ ! -f "$HOOKS_CONFIG" ]]; then
  exit 0
fi

python3 << DISPATCH_SCRIPT
import json, subprocess, os, sys

config_path = "${HOOKS_CONFIG}"
step        = "${STEP}"
event       = "${EVENT}"
phase       = "${PHASE}"
timestamp   = "${TIMESTAMP}"

try:
    config = json.load(open(config_path))
except Exception:
    sys.exit(0)

hooks = config.get("hooks", [])
env   = {**os.environ}

for hook in hooks:
    if not hook.get("enabled", True):
        continue

    hook_event = hook.get("event", "")

    # Match patterns: "assess:begin", "*:end", "reflect:*", "*:*"
    step_pat, _, evt_pat = hook_event.partition(":")
    step_match = step_pat in ("*", step)
    evt_match  = evt_pat  in ("*", event)

    if not (step_match and evt_match):
        continue

    action     = hook.get("action", {})
    atype      = action.get("type", "command")
    raw_cmd    = action.get("command", "")
    timeout    = action.get("timeout", 15)
    on_failure = action.get("on_failure", "warn")
    hook_id    = hook.get("id", "(unnamed)")

    # Variable substitution: \${VAR} -> env value
    cmd = raw_cmd
    for k, v in env.items():
        cmd = cmd.replace(f"\${{{k}}}", str(v))

    if atype == "command":
        try:
            result = subprocess.run(
                cmd, shell=True, env=env,
                capture_output=True, text=True, timeout=timeout
            )
            if result.returncode != 0:
                msg = result.stderr.strip()[:120] or result.stdout.strip()[:120]
                if on_failure == "warn":
                    print(f"  [warn] hook '{hook_id}' exited {result.returncode}: {msg}")
                elif on_failure == "error":
                    print(f"  [error] hook '{hook_id}' failed: {msg}")
                    sys.exit(1)
                # on_failure == "ignore": silent
            else:
                out = result.stdout.strip()
                if out:
                    print(f"  [ok]   hook '{hook_id}': {out[:120]}")
        except subprocess.TimeoutExpired:
            print(f"  [warn] hook '{hook_id}' timed out after {timeout}s")
        except Exception as ex:
            print(f"  [warn] hook '{hook_id}' error: {ex}")
    else:
        print(f"  [info] hook '{hook_id}': unsupported type '{atype}' -- skipped")

DISPATCH_SCRIPT

exit 0
